#!/usr/bin/env bash
# Generated by Claude (Anthropic's AI assistant, via Claude Code), October 2026. See Tools/Publish/README.md.
# Builds the public history from the dev repo and merges it into a branch of the public repo.
#
#   Tools/Publish/export-public.sh <dev-branch> <public-repo> [work-dir]
#   e.g. Tools/Publish/export-public.sh restructure /d/repos/Va.Si.Li-Lab-public
#
# 1. Clones <dev-branch> into a throwaway work dir (the dev repo itself is never rewritten).
# 2. Keeps only the paths in public-paths.txt, drops public-exclude.txt, scrubs public-replace.txt.
# 3. Aborts if any private path survived the filter (run check-public.sh before committing).
# 4. Creates branch sync/dev-<date> in <public-repo> that merges the filtered history into the
#    existing public history (both histories are kept). Nothing is pushed.
set -euo pipefail

DEV_BRANCH=${1:?dev branch}
PUBLIC_REPO=${2:?path to public repo}
HERE=$(cd "$(dirname "$0")" && pwd)
DEV_REPO=$(git -C "$HERE" rev-parse --show-toplevel)
WORK=${3:-$(mktemp -d)}/filtered
BRANCH="sync/dev-$(date +%Y%m%d)"
FILTER_REPO="uvx git-filter-repo"   # needs uv; or install git-filter-repo and use it directly
# Long Asset paths on Windows; set for this run only instead of changing any repo config
export GIT_CONFIG_COUNT=1 GIT_CONFIG_KEY_0=core.longpaths GIT_CONFIG_VALUE_0=true

echo "== Cloning $DEV_BRANCH into $WORK"
rm -rf "$WORK"
git clone -q --no-checkout --single-branch --branch "$DEV_BRANCH" "$DEV_REPO" "$WORK"
cd "$WORK"
git remote remove origin
git tag -l | xargs -r git tag -d >/dev/null   # dev tags point at private history

echo "== Filtering history"
$FILTER_REPO --force --quiet --paths-from-file "$HERE/public-paths.txt"
$FILTER_REPO --force --quiet --invert-paths --paths-from-file "$HERE/public-exclude.txt"
$FILTER_REPO --force --quiet --replace-text "$HERE/public-replace.txt"
git reset -q --hard
git reflog expire --expire=now --all && git gc -q --prune=now --aggressive
echo "   $(git rev-list --count HEAD) commits, $(git count-objects -vH | sed -n 's/size-pack: //p') packed"

echo "== Checking filtered history"
if git log --all --format= --name-only | grep -qE '^Assets/(LabPrivate|Samples|ThirdParty/AssetStore|Oculus)/|/Local/|\.(keystore|jks)$'; then
    echo "private paths survived the filter, aborting"; exit 1
fi
FILTERED_HEAD=$(git rev-parse HEAD)

echo "== Merging into $PUBLIC_REPO ($BRANCH)"
# Work in a temporary worktree so the public repo's own checkout (and its untracked files) stay untouched
WT="$WORK-public"
FILTERED_REF=refs/remotes/dev-filtered/main
git -C "$PUBLIC_REPO" fetch -q "$WORK" "+HEAD:$FILTERED_REF"
git -C "$PUBLIC_REPO" worktree add -q -B "$BRANCH" "$WT" origin/main
cd "$WT"
git merge -q --allow-unrelated-histories --no-commit -s ours "$FILTERED_REF"
# Take the dev side for everything it owns; keep public-only files (docs, CI, README, licence)
git rm -r -q --ignore-unmatch Assets Packages ProjectSettings Tools .editorconfig
git checkout "$FILTERED_REF" -- .
git commit -q -m "Sync Va.Si.Li-Lab from dev ($DEV_BRANCH @ $(git -C "$DEV_REPO" rev-parse --short "$DEV_BRANCH"))"
cd "$PUBLIC_REPO"
git worktree remove --force "$WT"
echo "   done: review with 'git log --graph --oneline $BRANCH'; nothing was pushed"
